// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    W_WALLET c;

    function setUp() public {
        c = new W_WALLET(address(new Log()));
    }

    function testFuzz_property(uint256 deposit, uint256 unlockTime, uint256 am) public {
        vm.assume(deposit <= VALUE_CAP);
        deposit = bound(deposit, 1 ether, 100 ether);
        unlockTime = bound(unlockTime, 0, 1 days);
        am = bound(am, 1 ether, deposit);

        address actor = address(0xABCD);
        vm.deal(actor, deposit);
        vm.prank(actor);
        c.Put{value: deposit}(unlockTime);

        vm.warp(block.timestamp + 2 days);

        vm.prank(actor);
        c.Collect(am);

        (, uint256 balanceAfter) = c.Acc(actor);

        assertTrue(balanceAfter <= deposit - am + am, "balance unexpectedly increased");
    }
}
